#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll count_factor(ll n, ll prime) {
    ll count = 0;
    while (n > 0) {
        n /= prime;
        count += n;
    }
    return count;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, b;
    cin >> n >> b;

    vector<pair<ll, int>> factors;

    for (ll p = 2; p <= b / p; ++p) {
        if (b % p == 0) {
            int exponent = 0;
            while (b % p == 0) {
                b /= p;
                ++exponent;
            }
            factors.emplace_back(p, exponent);
        }
    }

    if (b > 1) {
        factors.emplace_back(b, 1);
    }

    ll answer = LLONG_MAX;
    for (const auto& [prime, exponent] : factors) {
        answer = min(answer, count_factor(n, prime) / exponent);
    }

    cout << answer << '\n';
    return 0;
}

